<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{ $t('clone_sub_type') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            {{ $t('duplicate_from') }}
            <span class="text-weight-bold">{{
              new_model['duplicate_from_name']
            }}</span>
          </div>
        </div>

        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="
                'full-width ' +
                (new_model['sub_doc_type_error'] ? 'column-error-border' : '')
              "
              v-model="new_model['sub_doc_type']"
              :placeholder="$t('name')"
              :hint="sub_doc_type_hint"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['sub_doc_type_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['sub_doc_type'] != ''">
                      {{ sub_doc_type_hint }}
                    </template>
                    <template v-else>
                      {{ $t('field_required') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="bg-grey-3" :label="$t('cancel')" v-close-popup />
        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { onlyCharactersAndunderscore } from 'src/utils/general';
import { documentSubTypesApiService } from 'src/services';
export default defineComponent({
  el: '#app',
    props: {
    copy_model: {} as any,
  },
  components: {},
  data() {
    return {
      sub_doc_type_hint: this.$t('only_characters_underscore'),
    };
  },
  setup() {
    let model = {} as { [k: string]: any };

    return {
      new_model: ref(model),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
  },
  methods: {
    setNewModel() {
      this.new_model['sub_doc_type'] = '';
      this.new_model['sub_doc_type_error'] = false;
      this.new_model = Object.assign(this.new_model, this.copy_model);
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      const data = {
        from_sub_doc_type: this.new_model['from_sub_doc_type'],
        to_sub_doc_type: this.new_model['sub_doc_type'],
      };

      const response = await documentSubTypesApiService.createCopy(data);
      if (response.success === false) {
        if (response.message) throw { message: response.message };
        throw response;
      }
      this.setNewModel();
      const event = new CustomEvent('row_cloned', { detail: response });
      document.dispatchEvent(event);
      notify.success('Record Created successfully');
    },

    validateRow(row: any) {
      let validate = true;
      row.sub_doc_type_error = false;
      row.title_error = false;

      if (
        !row['sub_doc_type'] ||
        row['sub_doc_type'].length == 0 ||
        !onlyCharactersAndunderscore(row['sub_doc_type'])
      ) {
        row.sub_doc_type_error = true;
        validate = false;
      }

      return validate;
    },
  },
});
</script>

<style lang="scss" scoped></style>
