<!--vbase-->
<template>
  <q-card style="width: 600px" v-if="doc_type_key">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{ $t('edit_sub_type') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="
                'full-width ' +
                (new_model['sub_doc_type_error'] ? 'column-error-border' : '')
              "
              v-model="new_model['sub_doc_type']"
              :placeholder="$t('name')"
              :hint="sub_doc_type_hint"
              readonly
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['sub_doc_type_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['sub_doc_type'] != ''">
                      {{ sub_doc_type_hint }}
                    </template>
                    <template v-else>
                      {{ $t('field_required') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>

        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="
                'full-width ' +
                (new_model['title_error'] ? 'column-error-border' : '')
              "
              v-model="new_model['title']"
              :placeholder="$t('title')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['title_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['title'] != ''">
                      {{ sub_doc_type_hint }}
                    </template>
                    <template v-else>
                      {{ $t('field_required') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, PropType } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { onlyCharactersAndunderscore } from 'src/utils/general';
import { documentSubTypesApiService } from 'src/services';
export default defineComponent({
  el: '#app',
    props: {
    edit_model: {} as PropType<{
      id: string;
      sub_doc_type: string;
      title: string;
      translation_key: string;
    }>,
    doc_type_key: {
      type: String,
      default: '',
    },
  },
  components: {},
  data() {
    return {
      title_hint: this.$t('only_characters_spaces'),
      sub_doc_type_hint: this.$t('only_characters_underscore'),
    };
  },
  setup() {
    let model = {} as { [k: string]: any };

    return {
      new_model: ref(model),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    if (!this.doc_type_key) {
      notify.error('Doc Type is missing');
      return;
    }
    this.setNewModel();
  },
  methods: {
    setNewModel() {
      this.new_model['title_error'] = false;
      this.new_model['sub_doc_type_error'] = false;
      this.new_model = Object.assign(this.new_model, this.edit_model);
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveRow() {
      const data = {
        id: this.new_model.id,
        title: this.new_model.title,
      };

      const response = await documentSubTypesApiService.edit(data);
      if (!response.success) {
        throw new Error(response.message);
        return;
      }
      this.setNewModel();
      const event = new CustomEvent('row_edited', { detail: data });
      document.dispatchEvent(event);
      notify.success('Record Update Successfully');
    },

    validateRow(row: any) {
      let validate = true;
      row.sub_doc_type_error = false;
      row.title_error = false;

      if (
        !row['sub_doc_type'] ||
        row['sub_doc_type'].length == 0 ||
        !onlyCharactersAndunderscore(row['sub_doc_type'])
      ) {
        row.sub_doc_type_error = true;
        validate = false;
      }

      if (!row['title'] || row['title'].length == 0) {
        row.title_error = true;
        validate = false;
      }

      return validate;
    },
  },
});
</script>

<style lang="scss" scoped></style>
