<!--vbase-->
<template>
  <template v-if="doc_type_key">
    <div>
      <f-btn
        class="float-right"
        icon="add"
        :label="$t('new')"
        @click="display_create_dialog = true"
      />
    </div>

    <div class="container">
      <div class="full-width">
        <DocBitsTable
          :rows="rows"
          :columns="columns"
          row-key="name"
          table-id="sub_doc_types_table"
          :loading="processing"
          :features="{
            sorting: false,
            filtering: false,
            selection: false,
            bulkActions: false,
            rowActions: true,
            resizable: false,
            pagination: false,
            columnReorder: false,
            stickyLastColumn: true,
          }"
          :row-actions="rowActions"
          no-data-label="no_record_found"
          flat-style
          @row-action="handleRowAction"
        />
      </div>
    </div>

    <q-dialog v-model="delete_confirm" persistent>
      <q-card>
        <q-card-section
          class="row"
          style="justify-content: center; display: flex"
        >
          <q-avatar icon="warning" color="primary" />
        </q-card-section>

        <q-card-section class="row items-center">
          <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
        </q-card-section>

        <q-card-actions align="right">
          <f-btn
            appearance="cancel"
            :label="$t('cancel')"
            v-close-popup
          />
          <f-btn
            :label="$t('delete')"
            v-close-popup
            @click="deleteRow()"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <q-dialog
      v-model="display_create_dialog"
      persistent
      @keydown.esc="display_create_dialog = false"
    >
      <Create :doc_type_key="doc_type_key"></Create>
    </q-dialog>

    <q-dialog
      v-model="display_create_copy_dialog"
      persistent
      @keydown.esc="display_create_copy_dialog = false"
    >
      <CreateCopy :copy_model="copy_model"></CreateCopy>
    </q-dialog>

    <q-dialog
      v-model="display_edit_dialog"
      persistent
      @keydown.esc="display_edit_dialog = false"
    >
      <Edit :doc_type_key="doc_type_key" :edit_model="edit_model"></Edit>
    </q-dialog>

    <q-inner-loading :showing="processing">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </template>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import Create from './Create.vue';
import Edit from './Edit.vue';
import CreateCopy from './CreateCopy.vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { documentSubTypesApiService } from 'src/services';
import LayoutBuilderBtn from 'src/pages/Settings/LayoutBuilder/EditOrCreateBtn.vue';
import { formBuilderRouter } from 'src/formBuilder/utils/formBuilderRouter';
import { useFormBuilderStore } from 'src/store/main';
import { useDropdownStore } from 'src/store/main';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  el: '#app',
    components: {
    Create,
    Edit,
    LayoutBuilderBtn,
    CreateCopy,
    DocBitsTable,
  },
  data() {
    return {
      doc_type_key: '',
    };
  },
  mounted() {
    this.initView();
    document.addEventListener('row_added', this.rowAdded);
    document.addEventListener('row_cloned', this.rowClonedDone);
    document.addEventListener('row_edited', this.rowEdited);
    document.addEventListener(
      'update_current_user_orgs',
      this.updateCurrentUserOrganizations,
    );
  },
  methods: {
    async initView() {
      try {
        this.processing = true;
        this.doc_type_key = String(this.$route.params.doc_key);

        if (!this.doc_type_key) {
          throw { message: 'DOC_TYPE_MISSING' };
        }
        await this.getList();
        this.prepareColumns();
        this.getTemplatesForDocuments();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    rowAdded(e: any) {
      if (!e || !e.detail) {
        return;
      }
      this.display_create_dialog = false;
      this.addNewRow(e.detail);
      this.resetDocTypesSubDocTypes();
    },

    rowClonedDone(e: any) {
      if (!e || !e.detail) {
        return;
      }
      this.display_create_copy_dialog = false;
      this.getList();
      this.resetDocTypesSubDocTypes();
    },

    rowEdited(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.display_edit_dialog = false;
      this.editRow(e.detail);
      this.resetDocTypesSubDocTypes();
    },

    async deleteRow() {
      try {
        if (!this.delete_id) {
          return;
        }
        this.processing = true;
        await documentSubTypesApiService.delete(this.delete_id);

        let delete_index = -1;
        this.rows.forEach((row: any, index: any) => {
          if (row['id'] === this.delete_id) {
            delete_index = index;
          }
        });

        if (delete_index !== -1) {
          delete this.rows[delete_index];
        }

        this.delete_id = '';
        await this.resetDocTypesSubDocTypes();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async getList() {
      this.processing = true;
      const response = await documentSubTypesApiService.get(this.doc_type_key);
      if (!response.data) {
        return;
      }
      this.prepareRows(response.data);
      this.processing = false;
    },

    prepareColumns() {
      this.columns = [
        {
          name: 'name',
          label: 'Name',
          field: 'name',
          align: 'left',
        },
      ] as UnifiedTableColumn[];
    },

    prepareRows(data: any) {
      if (!data) {
        return;
      }
      this.rows = [] as any;
      for (let [index, item] of Object.entries(data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
      }
    },

    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },

    editRow(row: any) {
      this.rows.find((r: any) => {
        if (r.id === row.id) {
          r.title = row.title;
        }
      });
    },

    manageSettings(settingName: string) {
      this.$router.push(settingName);
    },

    getSubDocTypeForDuplicate(name: any) {
      const found_row = this.rows.filter((row: any) => row.name === name);
      if (found_row.length == 0) {
        return String(name);
      }
      return name + '_copy';
    },

    copy(row: any) {
      this.copy_model = {
        sub_doc_type: this.getSubDocTypeForDuplicate(row.name + '_copy'),
        from_sub_doc_type: row.sub_doc_type_key,
        duplicate_from_name: row.name,
      };
      this.display_create_copy_dialog = true;
    },

    edit(row: any) {
      this.edit_model = {
        id: row.id,
        sub_doc_type: row.name,
        title: row.title,
        translation_key: row.translation_key,
      };
      this.display_edit_dialog = true;
    },

    handleRowAction({ action, row }: { action: string; row: any }) {
      switch (action) {
        case 'fields':
          this.manageSettings(
            '/settings/fields/' + row.doc_type_key + '/' + row.sub_doc_type_key,
          );
          break;
        case 'layout':
          this.manageSettings(
            formBuilderRouter.getDetailViewRoute({
              doc_type_key: row.doc_type_key,
              sub_doc_type_key: row.sub_doc_type_key,
            }),
          );
          break;
        case 'scripts':
          this.manageSettings(
            '/settings/manage-scripts/' + row.doc_type_key + '/' + row.sub_doc_type_key,
          );
          break;
        case 'copy':
          this.copy(row);
          break;
        case 'edit':
          this.edit(row);
          break;
        case 'delete':
          this.delete_id = row.id;
          this.delete_confirm = true;
          break;
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { getTemplatesForDocuments } = form_builder_store;

    const dropdown_store = useDropdownStore();
    const { resetDocTypesSubDocTypes } = dropdown_store;

    const rowActions: RowActionItem[] = [
      { key: 'fields', label: 'fields', icon: 'list' },
      { key: 'layout', label: 'layout_builder_module', icon: 'view_quilt' },
      { key: 'scripts', label: 'scripts', icon: 'code' },
      { key: 'copy', label: 'copy', icon: 'content_copy' },
      { key: 'edit', label: 'edit', icon: 'edit' },
      { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true },
    ];

    return {
      resetDocTypesSubDocTypes,
      getTemplatesForDocuments,
      display_users_dialog: ref(false),
      display_create_dialog: ref(false),
      display_create_copy_dialog: ref(false),
      display_edit_dialog: ref(false),
      copy_model: ref({} as any),
      edit_model: ref({} as any),
      selectedId: ref(''),
      selectedName: ref(''),
      columns: ref([] as UnifiedTableColumn[]),
      rows: ref([] as any),
      delete_confirm: ref(false),
      delete_id: ref(''),
      processing: ref(false),
      LAYOUT_BUILDER_MODULE: ref(true),
      rowActions,
    };
  },
});
</script>
